-- D68 (the owner, 2026-10-31; built 2026-11-08, F148): the BAS chart at four digits — the account the accountant
-- books (`6540`, `6072`), not the three-digit main account without its 0 (`654`). BAS's own levels: class (1 digit)
-- · account group (2, the new `bas_groups`) · main account (`NNN0`) · sub-account (`NNN1`–`NNN9`, `parent_code`).
--
-- One migration, in this order: the chart's rows are added beside the old ones; every stored code `NNN` becomes
-- `NNN0` everywhere a code is kept; the three-digit rows go. A stored code with no four-digit main account refuses
-- the migration, naming it — nothing is dropped silently. The business keys carry the short code, not the account:
-- nothing is renumbered (FR-3). The chart rows are generated by `prisma/data/parse-bas.mjs` from BAS's files
-- (licensed, never committed).

CREATE TYPE "bas_account_kind" AS ENUM ('main', 'sub');

CREATE TABLE "bas_groups" (
    "code"       VARCHAR(2)  NOT NULL,
    "class_num"  INTEGER     NOT NULL,
    "name"       TEXT        NOT NULL,
    "name_en"    TEXT,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "bas_groups_pkey" PRIMARY KEY ("code")
);
-- reference data, read-only for the app (as `bas_categories`, 20260312055000)
REVOKE INSERT, UPDATE, DELETE ON TABLE "bas_groups" FROM af_app;
GRANT SELECT ON TABLE "bas_groups" TO af_app;

ALTER TABLE "bas_categories"
    ADD COLUMN "group_code"  VARCHAR(2),
    ADD COLUMN "kind"        "bas_account_kind",
    ADD COLUMN "parent_code" VARCHAR(4);

-- the chart is written by migrations only: its rules swallow every write, so they step aside for this one
DROP RULE IF EXISTS "no_insert_bas" ON "bas_categories";
DROP RULE IF EXISTS "no_update_bas" ON "bas_categories";
DROP RULE IF EXISTS "no_delete_bas" ON "bas_categories";

-- ── the chart (generated) ───────────────────────────────────────────────────────────────────────────────────
-- generated by prisma/data/parse-bas.mjs from BAS kontoplan 2026 (Swedish) + BAS 2025 (English)
-- 70 groups, 1282 accounts (472 main, 810 sub)

-- ── end of the chart ────────────────────────────────────────────────────────────────────────────────────────

-- the owner's short codes and curated names on the old row follow it to `NNN0` (the parser's table and the
-- stored row agree; the stored row wins — it is what the tenant has seen)
UPDATE "bas_categories" n
   SET "suggested_alias" = COALESCE(o."suggested_alias", n."suggested_alias"),
       "name_fr"         = COALESCE(o."name_fr", n."name_fr")
  FROM "bas_categories" o
 WHERE length(o."code") = 3 AND n."code" = o."code" || '0';

-- every stored code must have its four-digit main account — else stop, naming the codes
DO $$
DECLARE
    missing TEXT;
BEGIN
    SELECT string_agg(DISTINCT c, ', ' ORDER BY c) INTO missing
      FROM (
            SELECT "bas_code" AS c FROM "bank_transactions"      WHERE "bas_code" IS NOT NULL
  UNION ALL SELECT "bas_code"      FROM "categorisation_rules"   WHERE "bas_code" IS NOT NULL
  UNION ALL SELECT "bas_code"      FROM "expenses"
  UNION ALL SELECT "bas_code"      FROM "journal_entries"        WHERE "bas_code" IS NOT NULL
  UNION ALL SELECT "bas_code"      FROM "subscriptions"
  UNION ALL SELECT "bas_code"      FROM "supplier_invoices"
  UNION ALL SELECT "bas_code"      FROM "supplier_invoice_lines"
  UNION ALL SELECT "bas_code"      FROM "tenant_bas_preferences"
  UNION ALL SELECT "default_bas_category_code" FROM "partners" WHERE "default_bas_category_code" IS NOT NULL
           ) s
     WHERE length(c) = 3
       AND NOT EXISTS (SELECT 1 FROM "bas_categories" b WHERE b."code" = s.c || '0');
    IF missing IS NOT NULL THEN
        RAISE EXCEPTION 'bas_four_digit: no four-digit account for the stored code(s) %', missing;
    END IF;
END $$;

-- `NNN` → `NNN0` wherever a code is kept (the owner's facts — no lock trigger guards them)
UPDATE "bank_transactions"      SET "bas_code" = "bas_code" || '0' WHERE length("bas_code") = 3;
UPDATE "categorisation_rules"   SET "bas_code" = "bas_code" || '0' WHERE length("bas_code") = 3;
UPDATE "expenses"               SET "bas_code" = "bas_code" || '0' WHERE length("bas_code") = 3;
UPDATE "journal_entries"        SET "bas_code" = "bas_code" || '0' WHERE length("bas_code") = 3;
UPDATE "subscriptions"          SET "bas_code" = "bas_code" || '0' WHERE length("bas_code") = 3;
UPDATE "supplier_invoices"      SET "bas_code" = "bas_code" || '0' WHERE length("bas_code") = 3;
UPDATE "supplier_invoice_lines" SET "bas_code" = "bas_code" || '0' WHERE length("bas_code") = 3;
UPDATE "tenant_bas_preferences" SET "bas_code" = "bas_code" || '0' WHERE length("bas_code") = 3;
UPDATE "partners" SET "default_bas_category_code" = "default_bas_category_code" || '0'
 WHERE length("default_bas_category_code") = 3;

-- the BAS proposals' payloads (F98): the account and its alternatives
UPDATE "proposals"
   SET "payload" = jsonb_set("payload", '{basCode}', to_jsonb(("payload" ->> 'basCode') || '0'))
 WHERE "kind" = 'bas' AND length("payload" ->> 'basCode') = 3;
UPDATE "proposals"
   SET "payload" = jsonb_set("payload", '{alternatives}', (
         SELECT COALESCE(jsonb_agg(
                  CASE WHEN length(a ->> 'basCode') = 3
                       THEN jsonb_set(a, '{basCode}', to_jsonb((a ->> 'basCode') || '0'))
                       ELSE a END), '[]'::jsonb)
           FROM jsonb_array_elements("payload" -> 'alternatives') a))
 WHERE "kind" = 'bas' AND jsonb_typeof("payload" -> 'alternatives') = 'array';

-- the three-digit rows go (a code still pointing at one makes this fail — the guard above names it first)
DELETE FROM "bas_categories" WHERE length("code") = 3;

ALTER TABLE "bas_categories"
    ALTER COLUMN "group_code" SET NOT NULL,
    ALTER COLUMN "kind" SET NOT NULL,
    ADD CONSTRAINT "bas_categories_group_code_fkey" FOREIGN KEY ("group_code") REFERENCES "bas_groups"("code")
        ON DELETE RESTRICT ON UPDATE CASCADE,
    ADD CONSTRAINT "bas_categories_parent_code_fkey" FOREIGN KEY ("parent_code") REFERENCES "bas_categories"("code")
        ON DELETE RESTRICT ON UPDATE CASCADE,
    ADD CONSTRAINT "bas_categories_code_four_digits" CHECK ("code" ~ '^[0-9]{4}$');
CREATE INDEX "bas_categories_group_code_idx" ON "bas_categories"("group_code");

-- read-only again
CREATE RULE "no_insert_bas" AS ON INSERT TO "bas_categories" DO INSTEAD NOTHING;
CREATE RULE "no_update_bas" AS ON UPDATE TO "bas_categories" DO INSTEAD NOTHING;
CREATE RULE "no_delete_bas" AS ON DELETE TO "bas_categories" DO INSTEAD NOTHING;
